using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

namespace StardewValley.Pokemon;

public static class PokemonCanonicalData
{
	private static Dictionary<string, List<(int Level, string Move)>> _levelUpData;
	private static Dictionary<string, HashSet<string>> _allLearnables;
	private static bool _initialized = false;
	private static readonly object _lock = new();

	public static void EnsureLoaded()
	{
		if (_initialized) return;
		lock (_lock)
		{
			if (_initialized) return;
			_levelUpData = new(StringComparer.OrdinalIgnoreCase);
			_allLearnables = new(StringComparer.OrdinalIgnoreCase);

			string path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Content", "Pokemon", "canonical_learnsets.json");
			if (!File.Exists(path))
			{
				// Check relative to Game1.content or parent
				string alt = Path.Combine(Directory.GetCurrentDirectory(), "Content", "Pokemon", "canonical_learnsets.json");
				if (File.Exists(alt)) path = alt;
				else
				{
					// Search in workspace
					string devAlt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "..", "..", "..", "Content", "Pokemon", "canonical_learnsets.json");
					if (File.Exists(devAlt)) path = devAlt;
				}
			}

			if (File.Exists(path))
			{
				try
				{
					using var stream = File.OpenRead(path);
					using var doc = JsonDocument.Parse(stream);
					var root = doc.RootElement;

					if (root.TryGetProperty("levelUp", out var lvlProp))
					{
						foreach (var spec in lvlProp.EnumerateObject())
						{
							var list = new List<(int Level, string Move)>();
							foreach (var item in spec.Value.EnumerateArray())
							{
								int lvl = item[0].GetInt32();
								string mv = item[1].GetString();
								list.Add((lvl, mv));
							}
							string key = NormalizeKey(spec.Name);
							_levelUpData[key] = list;
						}
					}

					if (root.TryGetProperty("allLearnables", out var allProp))
					{
						foreach (var spec in allProp.EnumerateObject())
						{
							var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
							foreach (var item in spec.Value.EnumerateArray())
							{
								set.Add(item.GetString());
							}
							string key = NormalizeKey(spec.Name);
							_allLearnables[key] = set;
						}
					}
				}
				catch (Exception ex)
				{
					Game1.log?.Error($"Error loading canonical_learnsets.json: {ex.Message}");
				}
			}

			_initialized = true;
		}
	}

	public static string NormalizeKey(string name)
	{
		if (string.IsNullOrEmpty(name)) return "";
		return name.Replace(" ", "").Replace("-", "").Replace("_", "").ToLowerInvariant();
	}

	public static List<(int Level, string Move)> GetLevelUpLearnset(string speciesName)
	{
		EnsureLoaded();
		string key = NormalizeKey(speciesName);
		if (_levelUpData != null && _levelUpData.TryGetValue(key, out var list))
		{
			return list;
		}
		return null;
	}

	public static string GetMoveLearnedAtLevel(string speciesName, int level)
	{
		var list = GetLevelUpLearnset(speciesName);
		if (list == null) return null;
		for (int i = list.Count - 1; i >= 0; i--)
		{
			if (list[i].Level == level)
			{
				return list[i].Move;
			}
		}
		return null;
	}

	public static List<string> GetMovesForInitialLevel(string speciesName, int level)
	{
		var list = GetLevelUpLearnset(speciesName);
		if (list == null || list.Count == 0) return null;

		var learnedSoFar = new List<string>();
		foreach (var entry in list)
		{
			if (entry.Level <= level)
			{
				learnedSoFar.Remove(entry.Move); // Re-learning or updating position
				learnedSoFar.Add(entry.Move);
			}
		}

		if (learnedSoFar.Count == 0 && list.Count > 0)
		{
			learnedSoFar.Add(list[0].Move);
		}

		// Keep up to 4 most recent moves
		int count = Math.Min(4, learnedSoFar.Count);
		int start = learnedSoFar.Count - count;
		return learnedSoFar.GetRange(start, count);
	}

	public static bool IsCanonicallyTeachable(string speciesName, string moveName)
	{
		EnsureLoaded();
		string key = NormalizeKey(speciesName);
		if (_allLearnables != null && _allLearnables.TryGetValue(key, out var set))
		{
			return set.Contains(moveName);
		}
		return false;
	}
